NAME = 'SloKJV: Slovenian translation of Holy Bible King James Version (1769)'
BOOK = 'Nehemiah'

CHAPTERS = {
    1: {
        1: 'Besede Nehemija, Hahaljájevega sina. Pripetilo se je v mesecu kislévu, v dvajsetem letu, medtem ko sem bil v palači Suze,',
        2: 'da je prišel Hananí, eden izmed mojih bratov, on in nekateri možje iz Juda. Vprašal sem jih glede Judov, ki so pobegnili, ki so preostali od ujetništva in glede Jeruzalema.',
        3: 'Rekli so mi: »Ostanek, ki je ostal od ujetništva, tam v provinci, je v veliki stiski in graji. Prav tako je porušeno jeruzalemsko obzidje in njegova velika vrata so požgana z ognjem.«',
        4: 'In pripetilo se je, ko sem slišal te besede, da sem se usedel, jokal in žaloval določene dni in se postil ter molil pred Bogom nebes',
        5: 'in rekel: »Rotim te, oh Gospod Bog nebes, veliki in strašni Bog, ki ohranja zavezo in usmiljenje za tiste, ki ga ljubijo in obeležujejo njegove zapovedi.',
        6: 'Naj bo tvoje uho sedaj pozorno in tvoje oči odprte, da boš lahko slišal molitev svojega služabnika, ki jo sedaj molim pred teboj podnevi in ponoči zaradi tvojih služabnikov, Izraelovih otrok in priznavam grehe Izraelovih otrok, ki smo jih zagrešili zoper tebe. Tako jaz, kakor hiša mojega očeta smo grešili.',
        7: 'Zoper tebe smo postopali zelo izprijeno in se nismo držali zapovedi niti zakonov niti sodb, ki si jih zapovedal svojemu služabniku Mojzesu.',
        8: 'Spomni se, rotim te, besede, ki jo zapoveduješ svojemu služabniku Mojzesu, rekoč: › Če grešite, vas bom razkropil na tuje, med narode.',
        9: 'Toda če se obrnete k meni in se držite mojih zapovedi in jih izpolnjujete, čeprav bi bili izmed vas vrženi v najbolj oddaljen del neba, jih bom vendar zbral od tam in jih privedel na kraj, ki sem ga izbral, da tam postavim svoje ime.‹',
        10: 'Torej ti so tvoji služabniki in tvoje ljudstvo, ki si jih odkupil s svojo veliko oblastjo in s svojo močno roko.',
        11: 'Oh Gospod, rotim te, naj bo sedaj tvoje uho pozorno k molitvi tvojega služabnika in k molitvi tvojih služabnikov, ki se želijo bati tvojega imena. Prosim te, naredi svojega služabnika ta dan uspešnega in zagotovi mu usmiljenje pred očmi tega človeka.« Kajti bil sem kraljevi dvorni točaj.',
    },
    2: {
        1: 'Pripetilo se je v mesecu nisánu, v dvanajstem letu kralja Artakserksa, da je bilo pred njim vino. Vzel sem vino in ga izročil kralju. Torej poprej v njegovi prisotnosti nisem bil žalosten.',
        2: 'Zato mi je kralj rekel: »Zakaj je tvoje obličje žalostno, ker vidim, da nisi bolan? To ni nič drugega kakor bridkost srca.« Potem sem bil zelo boleče prestrašen',
        3: 'in rekel kralju: »Naj kralj živi na veke. Zakaj naj bi moje obličje ne bilo žalostno, ko [pa] mesto, kraj mavzolejev mojih očetov, leži opustošeno in so njegova velika vrata použita z ognjem?«',
        4: 'Potem mi je kralj odgovoril: »Za kaj delaš zahtevo?« Tako sem molil k Bogu nebes.',
        5: 'Kralju sem rekel: »Če kralju ugaja in je tvoj služabnik našel naklonjenost v tvojem pogledu, da bi me hotel poslati v Judejo, v mesto mavzolejev mojih očetov, da ga lahko zgradim.«',
        6: 'Kralj mi je rekel (tudi kraljica je sedela ob njem): »Kako dolgo bo trajalo tvoje potovanje? In kdaj se boš vrnil?« Tako je kralju ugajalo, da me pošlje, in določil sem mu čas.',
        7: 'Poleg tega sem kralju rekel: »Če to ugaja kralju, naj mi bodo dana pisma, za voditelje onkraj reke, da me lahko pošljejo preko, dokler ne pridem v Judejo,',
        8: 'in pismo Asáfu, čuvaju kraljevega gozda, da mi bo lahko dal les, da naredim bruna za velika vrata palače, ki so spadala k hiši in za mestno obzidje in za hišo, v katero bom vstopil.« In kralj mi je zagotovil, glede na dobro roko mojega Boga nad menoj.',
        9: 'Potem sem prišel k voditeljem preko reke in jim dal kraljeva pisma. Torej kralj je z menoj poslal vojne poveljnike in konjenike.',
        10: 'Ko sta Sanbalát Horónčan in služabnik Tobija, Amónec, slišala o tem, ju je to silno užalostilo, da je tja prišel človek, da išče blaginjo Izraelovih otrok.',
        11: 'Tako sem prišel v Jeruzalem in bil tam tri dni.',
        12: 'Vstal sem ponoči, jaz in nekaj malega mož z menoj. Niti nisem nobenemu možu povedal, kaj je Bog položil na moje srce, da storim pri Jeruzalemu. Niti ni bila z menoj nobena žival, razen živali, na kateri sem jahal.',
        13: 'Ponoči sem odšel ven pri Dolinskih velikih vratih, celo pred zmajevim vodnjakom in do gnojne odprtine in ogledal sem si jeruzalemske zidove, ki so bili porušeni in njegova velika vrata, ki so bila použita z ognjem.',
        14: 'Potem sem odšel naprej do velikih studenčnih vrat in do kraljevega ribnika, toda tam ni bilo prostora za žival, ki je bila pod menoj, da gre mimo.',
        15: 'Potem sem ponoči odšel gor, poleg potoka in gledal obzidje in se obrnil nazaj in vstopil pri velikih dolinskih vratih in tako sem se vrnil.',
        16: 'Vladarji niso vedeli, kam sem odšel ali kaj sem storil, niti do tega trenutka tega še nisem povedal Judom, niti duhovnikom, niti plemičem, niti vladarjem, niti preostalim, ki so opravljali delo.',
        17: 'Potem sem jim rekel: »Vi vidite stisko, v kateri smo, kako Jeruzalem leži opustošen in so njegova velika vrata požgana z ognjem. Pridite in gradimo jeruzalemsko obzidje, da ne bomo več v grajo.«',
        18: 'Potem sem jim povedal o roki svojega Boga, ki je bila dobra nad menoj, kot tudi kraljeve besede, ki mi jih je govoril. Rekli so: »Vzdignimo se in gradimo.« Tako so okrepili svoje roke za to dobro delo.',
        19: 'Toda ko so Sanbalát Horónčan in služabnik Tobija, Amónec in Arabec Gešem to slišali, so se smejali do norčevanja, nas prezirali in rekli: »Kaj je ta stvar, ki jo počnete. Ali se hočete upreti zoper kralja?«',
        20: 'Potem sem jim odgovoril in jim rekel: »Bog nebes, on nas bo naredil uspešne, zato bomo mi, njegovi služabniki, vstali in gradili. Toda vi nimate deleža niti pravice niti spomina v Jeruzalemu.«',
    },
    3: {
        1: 'Potem je vstal Eljašíb, véliki duhovnik, s svojimi brati duhovniki in zgradili so Ovčja velika vrata. Posvetili so jih in vstavili vrata, celo do stolpa Mea so to posvetili, do Hananélovega stolpa.',
        2: 'Poleg njega so gradili možje iz Jerihe. Poleg njih je gradil Imríjev sin Zahúr.',
        3: 'Toda Ribja velika vrata so gradili Senaájevi sinovi, ki so tudi položili njena bruna in postavili njena vrata, njene ključavnice in njene zapahe.',
        4: 'Poleg njih je popravljal Meremót, Urijájev sin, Kocov sin. Poleg njih je popravljal Mešulám, Berehjájev sin, Mešezabélov sin. In poleg njih Baanájev sin Cadók.',
        5: 'Poleg njih so popravljali Tekójčani, toda njihovi plemiči svojih vratov niso pristavili k delu njihovega Gospoda.',
        6: 'Poleg tega sta Stara velika vrata popravljala Jojadá, sin Paséaha in Mešulám, Besodjájev sin. Položila sta njena bruna in postavila njena vrata in njene ključavnice in njene zapahe.',
        7: 'Poleg njiju so popravljali Gibeónec Melatjá in Meronočán Jadón, možje iz Gibeóna in iz Micpe, do prestola voditelja na tej strani reke.',
        8: 'Poleg njega je popravljal Uziél, Harhajájev sin izmed zlatarjev. Poleg njega je popravljal tudi Hananjá, sin enega izmed lekarnarjev in Jeruzalem so utrdili do širokega zidu.',
        9: 'Poleg njih je popravljal Hurov sin Refajá, vladar polovice Jeruzalema.',
        10: 'Poleg njega je popravljal Harumáfov sin Jedajája, celo nasproti svoje hiše. Poleg njega je popravljal Hašabnejájev sin Hatúš.',
        11: 'Harímov sin Malkijája in Pahat Moábov sin Hašúb sta popravljala drug kos in stolp talilne peči.',
        12: 'Poleg njega je popravljal Lohéšev sin Šalúm, vladar polovice Jeruzalema, on in njegove hčere.',
        13: 'Dolinska velika vrata so popravljali Hanún in prebivalci Zanóaha. Zgradili so jih in postavili njena vrata, njene ključavnice in njene zapahe in tisoč komolcev na obzidju do Gnojnih velikih vrat.',
        14: 'Toda Gnojna velika vrata je popravljal Rehábov sin Malkijáj, vladar dela Bet Kerema. Zgradil jih je, postavil njena vrata, njene ključavnice in njene zapahe.',
        15: 'Toda Studenčna velika vrata je popravljal Kolhozéjev sin Šalún, vladar dela Micpe. On je to zgradil, pokril in postavil njena vrata, njene ključavnice in njene zapahe in zid ribnika Síloa, poleg kraljevega vrta in do stopnic, ki gredo dol od Davidovega mesta.',
        16: 'Za njim je popravljal Azbúkov sin Nehemija, vladar polovice Bet Cura, do kraja nasproti Davidovih mavzolejev in do ribnika, ki je bil narejen in do hiše mogočnega.',
        17: 'Za njim so popravljali Lévijevci, Baníjev sin Rehúm. Poleg njega je na svojem delu popravljal Hašabjá, vladar polovice Keíle.',
        18: 'Za njim so popravljali njihovi bratje, Henadádov sin Bavaj, vladar polovice Keíle.',
        19: 'Poleg njega je popravljal Ješúajev sin Ecer, vladar Micpe, drug del nasproti vzpona do orožarne, ob [delu, kjer se] zid obrne.',
        20: 'Za njim je Zabájev sin Baruh vneto popravljal drugi kos, od [dela, kjer se] zid obrne, do vrat hiše vélikega duhovnika Eljašíba.',
        21: 'Za njim je drug del popravljal Meremót, Urijájev sin, Kocov sin, od vrat Eljašíbove hiše, celo do konca Eljašíbove hiše.',
        22: 'Za njim so popravljali duhovniki, možje ravnine.',
        23: 'Za njim sta nasproti njuni hiši popravljala Benjamin in Hašúb. Za njima je ob njegovi hiši popravljal Azarjá, Maasejájev sin, sin Ananjája.',
        24: 'Za njim je popravljal Henadádov sin Binúj, drug del od Azarjájeve hiše do [dela, kjer se] zid obrne, celo do vogala.',
        25: 'Uzájev sin Palál nasproti [dela, kjer se] zid obrne in stolpa, ki se nahaja zunaj kraljeve velike hiše, ki je bila ob dvorišču ječe. Za njim Paróšev sin Pedajá.',
        26: 'Poleg tega so Netinimci prebivali v Ofelu, do kraja nasproti Vodnih velikih vrat proti vzhodu in stolpa, ki se nahaja zunaj.',
        27: 'Za njimi so Tekójčani popravljali drug del, nasproti velikemu stolpu, ki leži zunaj, celo do ofelskega obzidja.',
        28: 'Od zgoraj, iznad Konjskih velikih vrat so popravljali duhovniki, vsak nasproti svoji hiši.',
        29: 'Za njimi je popravljal Imêrjev sin Cadók nasproti svoji hiši. Za njim je popravljal tudi Šehanjájev sin Šemajá, čuvaj Vzhodnih velikih vrat.',
        30: 'Za njim je drug del popravljal Šelemjájev sin Hananjá in Hanún, šesti Caláfov sin. Za njim je popravljal Berehjájev sin Mešulám nasproti svoje sobe.',
        31: 'Za njim je popravljal zlatarjev sin Malkijá do kraja Netinimcev in trgovcev, nasproti velikih vrat Mifkada in do vzpona vogala.',
        32: 'Med vzponom vogala, do Ovčjih velikih vrat, so popravljali zlatarji in trgovci.',
    },
    4: {
        1: 'Toda pripetilo se je, da ko je Sanbalát slišal, da smo gradili zid, da je bil besen in polastilo se ga je veliko ogorčenje in zasmehoval je Jude.',
        2: '§ Pred svojimi brati in vojsko Samarije je spregovoril ter rekel: »Kaj počno ti slabotni Judje? Mar se bodo utrdili?? Mar bodo žrtvovali? Mar bodo končali v [enem] dnevu? Mar bodo oživili kamne iz kupov smeti, ki so požgane?«',
        3: 'Torej Amónec Tobija je bil ob njem in rekel: »Celo to, kar so zgradili, če gre gor lisjak, bo torej porušil njihov kamniti zid.«',
        4: 'Prisluhni, oh naš Bog, kajti mi smo prezirani. Obrni njihovo grajo na njihovo lastno glavo in jih daj za plen v deželi ujetništva',
        5: 'in ne pokrij njihove krivičnosti in naj njihov greh ne bo izbrisan izpred tebe, kajti do jeze so te izzivali pred graditelji.',
        6: 'Tako smo gradili obzidje in vse obzidje je bilo združeno skupaj do njegove polovice, kajti ljudstvo je imelo um, da dela.',
        7: 'Toda pripetilo se je, da ko so Sanbalát, Tobija, Arabci, Amónci in Ašdódčani slišali, da so bili zidovi Jeruzalema postavljeni in da so se vrzeli začele zapolnjevati, potem so bili zelo besni',
        8: 'in vsi skupaj so skovali zaroto, da pridejo in se borijo zoper Jeruzalem in da to ovirajo.',
        9: 'Kljub temu smo naredili svojo molitev k svojemu Bogu in podnevi ter ponoči zaradi njih postavili stražo.',
        10: 'Juda je rekel: »Moč nosilcev bremen je oslabela in tam je veliko smeti, tako, da nismo zmožni graditi obzidja.«',
        11: 'Naši nasprotniki pa so rekli: »Ne bodo vedeli niti videli, dokler ne pridemo v sredo mednje in jih pobijemo in povzročimo, da delo preneha.«',
        12: 'Pripetilo pa se je, ko so prišli Judje, ki so prebivali poleg njih, da so nam desetkrat rekli: »Iz vseh krajev, od koder se boste vrnili k nam, bodo oni nad vami.«',
        13: 'Zato sem postavil na nižjih mestih za obzidjem in na višjih mestih, sem celo postavil ljudstvo po njihovih družinah, z njihovimi meči, njihovimi sulicami in njihovimi loki.',
        14: 'Pogledal sem, vstal in rekel plemičem, vladarjem in ostalemu ljudstvu: »Ne bojte se jih. Spominjajte se Gospoda, ki je velik in strašen in borite se za svoje brate, svoje sinove in svoje hčere, svoje žene in svoje hiše.«',
        15: 'Pripetilo se je, ko so naši sovražniki slišali, da nam je bilo to znano in je Bog njihovo namero privedel v nič, da smo se vsi izmed nas vrnili k obzidju, vsak k svojemu delu.',
        16: 'Pripetilo se je od tega časa naprej, da je polovica mojih služabnikov delala na delu, druga polovica pa je držala sulice, ščite, loke in brezrokavne verižne srajce in vladarji so bili zadaj za vso Judovo hišo.',
        17: 'Tisti, ki so gradili na obzidju in tisti, ki so nosili bremena, s tistimi, ki so prenašali, vsak je z eno roko opravljal delo, z drugo roko pa je držal orožje.',
        18: 'Kajti graditelji so gradili tako, da je imel vsakdo svoj meč opasan ob svoji strani. Tisti, ki je trobil na šofar, pa je bil poleg mene.',
        19: 'Rekel sem plemičem, vladarjem in ostalemu ljudstvu: »Delo je veliko in obsežno, mi pa smo na obzidju ločeni, eden daleč od drugega.',
        20: 'Na katerem mestu torej zaslišite glas šofarja, krenite tja k nam. Naš Bog se bo boril za nas.«',
        21: 'Tako smo se trudili na delu. Polovica izmed njih je sulice držala od jutranjega vzhoda do pojavitve zvezd.',
        22: 'Prav tako sem ljudstvu istočasno rekel: »Naj vsak s svojim služabnikom prenočuje znotraj Jeruzalema, da nam bodo ponoči lahko straža in se trudili podnevi.«',
        23: '§ Tako niti jaz, niti moji bratje, niti moji služabniki, niti ljudje na straži, ki so mi sledili, nihče izmed nas ni odložil svojih oblačil, razen, da jih je vsak slekel za pranje.',
    },
    5: {
        1: 'Tam je bilo veliko vpitje ljudstva in njihovih žena zoper njihove brate Jude.',
        2: 'Kajti tam so bili, ki so rekli: »Nas, naših sinov in naših hčera je mnogo. Zato zanje zbiramo žito, da bomo lahko jedli in živeli.«',
        3: 'Tam so bili tudi nekateri, ki so rekli: »Zaradi pomanjkanja smo zastavili svoje dežele, vinograde in hiše, da bi lahko kupili žito.«',
        4: 'Tam so bili tudi, ki so rekli: »Izposodili smo si denar za kraljevi davek in to [za ceno] naših dežel in vinogradov.',
        5: 'Vendar je sedaj naše meso kakor meso naših bratov, naši otroci kakor njihovi otroci. Glej, svoje sinove prinašamo v sužnost in svoje hčere, da bodo služabnice in nekatere izmed naših hčera so že privedene v sužnost. Niti to ni v naši moči, da jih odkupimo, kajti drugi možje imajo naše dežele in vinograde.«',
        6: 'Bil sem zelo jezen, ko sem slišal njihovo vpitje in te besede.',
        7: 'Potem sem se posvetoval s seboj in oštel plemiče in vladarje ter jim rekel: »Vi terjate obresti, vsakdo od svojega brata.« In zoper njih sem postavil velik zbor.',
        8: 'Rekel sem jim: »Po svoji zmožnosti smo odkupili svoje brate Jude, ki so bili prodani poganom. Vi pa boste celo prodajali svoje brate? Ali naj bi bili oni prodani nam?« Potem so ohranili svoj mir in nič niso našli, da bi odgovorili.',
        9: 'Prav tako sem rekel: »To ni dobro, kar delate. Ali ne bi morali hoditi v strahu našega Boga zaradi graje poganov, naših sovražnikov?',
        10: 'Tudi jaz in moji bratje in moji služabniki bi lahko od njih terjali denar in žito. Prosim vas, prenehajmo s tem oderuštvom.',
        11: 'Povrnite jim, prosim vas, celo ta dan, njihove dežele, njihove vinograde, njihove oljčne nasade in njihove hiše, tudi stoti del denarja in od žita, vina in olja, ki ste jih vzeli od njih.«',
        12: 'Potem so rekli: »Povrnili jim bomo in ničesar ne bomo zahtevali od njih. Storili bomo tako, kakor praviš.« Potem sem poklical duhovnike in od njih vzel prisego, da bi storili glede na to obljubo.',
        13: 'Prav tako sem stresel svoje naročje in rekel: »Tako naj Bog iztrese vsakega človeka iz njegove hiše in od njegovega truda, ki ne izpolni te obljube, celo tako bo iztresen in izpraznjen.« In vsa skupnost je rekla: »Amen« in hvalili so Gospoda. In ljudstvo je storilo glede na to obljubo.',
        14: 'Poleg tega od časa, ko sem bil določen, da bi bil njihov voditelj v Judovi deželi, od dvajsetega leta, celo do dvaintridesetega leta kralja Artakserksa, to je dvanajst let, jaz in moji bratje nismo jedli kruha od voditelja.',
        15: 'Toda prejšnji voditelji, ki so bili pred menoj, so bili v breme ljudstvu in so od njih jemali kruh in vino, poleg štiridesetih šeklov srebra. Da, celo njihovi služabniki so vladali nad ljudstvom. Toda zaradi Božjega strahu jaz nisem tako storil.',
        16: 'Da, prav tako sem nadaljeval pri delu tega obzidja niti nismo kupili nobene zemlje in vsi moji služabniki so bili zbrani tja k delu.',
        17: 'Poleg tega jih je bilo pri moji mizi sto petdeset izmed Judov in vladarjev, poleg tistih, ki so prišli k nam izmed poganov, ki so okoli nas.',
        18: 'Torej tega, kar je bilo dnevno pripravljeno zame, je bilo: en vol in šest izbranih ovc. Tudi perjad je bila pripravljena zame in enkrat na deset dni izbor vseh vrst vina. Vendar za vse to nisem zahteval kruha od voditelja, ker je bilo suženjstvo težko nad tem ljudstvom.',
        19: 'Misli name, moj Bog, za dobro, glede na vse, kar sem storil za to ljudstvo.',
    },
    6: {
        1: 'Pripetilo se je torej, ko so Sanbalát, Tobija, Arabec Gešem in ostali izmed naših sovražnikov slišali, da sem zgradil obzidje in da v njem ni ostalo nobene vrzeli (čeprav ob tistem času nisem postavil duri na velika vrata)',
        2: 'da sta Sanbalát in Gešem poslala k meni, rekoč: »Pridi, skupaj se srečajmo v eni izmed vasi, na ravnini Onó.« Toda mislila sta mi storiti vragolijo.',
        3: 'K njima sem poslal poslance, rekoč: »Jaz opravljam veliko delo, tako da ne morem priti dol. Zakaj bi delo prenehalo, medtem ko ga zapustim in pridem dol k vama?«',
        4: 'Vendar sta štirikrat poslala k meni na ta način, jaz pa sem jima odgovoril na isti način.',
        5: 'Potem je Sanbalát petič k meni poslal svojega služabnika na podoben način, z odprtim pismom v svoji roki,',
        6: 'v katerem je bilo zapisano: »Med pogani se govori in Gašmu pravi to, da se ti in Judje mislite upreti, kajti zaradi tega razloga gradiš obzidje, da bi lahko postal njihov kralj, glede na te besede.',
        7: 'Določil si tudi preroke, da o tebi oznanjajo v Jeruzalemu, rekoč: › Tam je kralj v Judu.‹ In sedaj bo to sporočeno kralju, glede teh besed. Pridite torej sedaj in skupaj sprejmimo nasvet.«',
        8: 'Potem sem poslal k njemu, rekoč: »Tukaj se niso storile nobene takšne stvari, kot ti praviš, temveč si jih hlinil iz svojega lastnega srca.«',
        9: 'Kajti oni vsi so nas prestrašili, rekoč: »Njihove roke bodo oslabele od dela, da to ne bo končano.« Sedaj torej, oh Bog, okrepi moje roke.',
        10: 'Zatem sem prišel v hišo Šemajája, sinú Delajája, sinú Mehetabéla, ki je bil zaprt. Rekel je: »Skupaj se srečajva v hiši Boga, znotraj templja in zapriva vrata templja, kajti prišli bodo, da te ubijejo. Da, ponoči bodo prišli, da te ubijejo.«',
        11: 'Rekel sem: »Ali naj bi takšen človek, kakor sem jaz, bežal? In kdo je tam, ki bi kakor sem jaz, šel v tempelj, da reši svoje življenje? Ne bom šel noter.«',
        12: 'Glej, zaznal sem, da ga ni poslal Bog, temveč, da je to prerokbo proglasil zoper mene, kajti najela sta ga Tobija in Sanbalát.',
        13: 'Zato je bil najet, da bi bil jaz prestrašen in tako storil in grešil in da bi lahko imela stvar za hudobno poročilo, da bi me lahko grajala.',
        14: 'Moj Bog, misli na Tobija in Sanbaláta glede na ta njuna dela in na prerokinjo Noádjo in ostale preroke, ki so me hoteli postaviti v strah.',
        15: 'Tako je bilo obzidje končano petindvajseti dan meseca elúla, v dvainpetdesetih dneh.',
        16: 'Pripetilo se je, da ko so vsi naši sovražniki slišali o tem in so vsi pogani, ki so bili okoli nas, videli te stvari, so bili zelo potrti v svojih lastnih očeh, kajti zaznali so, da je bilo to delo izvršeno od našega Boga.',
        17: 'Poleg tega so v tistih dneh Judovi plemiči poslali mnogo pisem Tobiju in pisma od Tobija so prihajala k njim.',
        18: 'Kajti v Judu so bili mnogi, ki so mu prisegli, ker je bil zet Aráhovega sina Šehanjája in njegov sin Johanán je vzel hčer Berehjájevega sina Mešuláma.',
        19: 'Pred menoj so poročali tudi njegova dobra dejanja in mu izrekli moje besede. In Tobija je pošiljal pisma, da me postavi v strah.',
    },
    7: {
        1: 'Pripetilo se je torej, ko je bilo obzidje zgrajeno in sem postavil vrata in so bili določeni vratarji, pevci in Lévijevci,',
        2: 'da sem dal svojemu bratu Hananíju in Hananjáju, vladarju palače, zadolžitev nad Jeruzalemom, kajti ta je bil zvest mož in bolj kot mnogi se je bal Boga.',
        3: 'Rekel sem jima: »Naj velika vrata Jeruzalema ne bodo odprta, dokler ne bo sonce vroče. Medtem ko stojijo poleg, naj vrata zaprejo in jih zapahnejo. Določite straže izmed prebivalcev Jeruzalema, vsakogar na svojo stražo in vsakdo naj bo nasproti svoji hiši.«',
        4: 'Torej mesto je bilo prostrano in veliko. Toda ljudstva v njem je bilo malo in hiše niso bile zgrajene.',
        5: 'Moj Bog je na moje srce položil, da zberem skupaj plemiče, vladarje in ljudstvo, da bi bili lahko prešteti po rodovniku. Našel sem seznam rodovnika izmed tistih, ki so prišli najprej gor in v njem našel zapisano:',
        6: '›To so otroci province, ki je šla gor iz ujetništva, od tistih, ki so bili odvedeni, ki jih je odvedel babilonski kralj Nebukadnezar in so ponovno prišli v Jeruzalem in v Judejo, vsak v svoje mesto,',
        7: 'ki so prišli z Zerubabélom, Ješúom, Nehemijem, Azarjájem, Raamjájem, Nahamánijem, Mordohajem, Bilšánom, Mispéretom, Bigvájem, Nehumom in Baanájem. Število, pravim, izmed mož Izraelovega ljudstva je bilo tole:',
        8: 'Paróševih otrok dva tisoč sto dvainsedemdeset.',
        9: 'Šefatjájevih otrok tristo dvainsedemdeset.',
        10: 'Aráhovih otrok šeststo dvainpetdeset.',
        11: 'Pahat Moábovih otrok, od otrok Ješúa in Joába, dva tisoč osemsto in osemnajst.',
        12: 'Elámovih otrok tisoč dvesto štiriinpetdeset.',
        13: 'Zatújevih otrok osemsto petinštirideset.',
        14: 'Zakájevih otrok sedemsto šestdeset.',
        15: 'Binújevih otrok šeststo oseminštirideset.',
        16: 'Bebájevih otrok šeststo osemindvajset.',
        17: 'Azgádovih otrok dva tisoč tristo dvaindvajset.',
        18: 'Adonikámovih otrok šeststo sedeminšestdeset.',
        19: 'Bigvájevih otrok dva tisoč sedeminšestdeset.',
        20: 'Adínovih otrok šeststo petinpetdeset.',
        21: 'Atêrjevih otrok, od Ezekíja, osemindevetdeset.',
        22: 'Hašúmovih otrok tristo osemindvajset.',
        23: 'Becájevih otrok tristo štiriindvajset.',
        24: 'Harífovih otrok sto dvanajst.',
        25: 'Gibeónovih otrok petindevetdeset.',
        26: 'Mož iz Betlehema in Netófe sto oseminosemdeset.',
        27: 'Mož iz Anatóta sto osemindvajset.',
        28: 'Mož iz Bet Azmáveta dvainštirideset.',
        29: 'Mož iz Kirját Jearíma, Kefíre in Beeróta sedemsto triinštirideset.',
        30: 'Mož iz Rame in Gebe šeststo enaindvajset.',
        31: 'Mož iz Mihmása sto dvaindvajset.',
        32: 'Mož iz Betela in Aja sto triindvajset.',
        33: 'Mož iz drugega Nebója dvainpetdeset.',
        34: 'Otrok iz drugega Eláma tisoč dvesto štiriinpetdeset.',
        35: 'Harímovih otrok tristo dvajset.',
        36: 'Jerihovih otrok tristo petinštirideset.',
        37: 'Otrok iz Loda, Hadída in Onója sedemsto enaindvajset.',
        38: 'Otrok iz Senaája tri tisoč devetsto trideset.',
        39: 'Duhovniki: Jedajájevih otrok iz Ješúove hiše devetsto triinsedemdeset.',
        40: 'Imêrjevih otrok tisoč dvainpetdeset.',
        41: 'Pašhúrjevih otrok tisoč dvesto sedeminštirideset.',
        42: 'Harímovih otrok tisoč sedemnajst.',
        43: 'Lévijevci: Ješúovih otrok, od Kadmiéla in Hodavjájevih otrok štiriinsedemdeset.',
        44: 'Pevci: Asáfovih otrok sto oseminštirideset.',
        45: 'Vratarji: Šalúmovih otrok, Atêrjevih otrok, Talmónovih otrok, Akúbovih otrok, Hatitájevih otrok in Šobájevih otrok sto osemintrideset.',
        46: 'Netinimci: Cihájevi otroci, Hasufájevi otroci, Tabaótovi otroci,',
        47: 'Kerósovi otroci, Siájevi otroci, Padónovi otroci,',
        48: 'Lebanájevi otroci, Hagabájevi otroci, Salmájevi otroci,',
        49: 'Hanánovi otroci, Gidélovi otroci, Gaharjevi otroci,',
        50: 'Reajájevi otroci, Recínovi otroci, Nekodájevi otroci,',
        51: 'Gazámovi otroci, Uzájevi otroci, Paséahovi otroci,',
        52: 'Besájevi otroci, Meunimovi otroci, Nefiséjevi otroci,',
        53: 'Bakbúkovi otroci, Hakufájevi otroci, Harhúrjevi otroci,',
        54: 'Baclitovi otroci, Mehidájevi otroci, Haršájevi otroci,',
        55: 'Barkósovi otroci, Siserájevi otroci, Temahovi otroci,',
        56: 'Necíahovi otroci in Hatifájevi otroci.',
        57: 'Otroci Salomonovih služabnikov: Sotájevi otroci, Soféretovi otroci, Peridájevi otroci,',
        58: 'Jaalájevi otroci, Darkónovi otroci, Gidélovi otroci,',
        59: 'Šefatjájevi otroci, Hatílovi otroci, Pohêret Cebájimovi otroci in Amónovi otroci.',
        60: 'Vseh Netinimcev in otrok Salomonovih služabnikov, je bilo tristo dvaindevetdeset.',
        61: 'In ti so bili tisti, ki so tudi odšli gor iz Tel Melaha, Tel Hareše, Kerúba, Adóna in Imêrja. Toda niso mogli pokazati hiše svojega očeta niti svojega semena, če so bili iz Izraela.',
        62: 'Delajájevih otrok, Tobijevih otrok, Nekodájevih otrok šeststo dvainštirideset.',
        63: 'Izmed duhovnikov: Habajájevi otroci, Kocovi otroci in otroci Barzilája, ki je vzel eno izmed hčera Gileádca Barzilája za ženo in je bil imenovan po njihovem imenu.',
        64: 'Ti so iskali svoj seznam med tistimi, ki so bili prešteti po rodovniku, toda ta ni bil najden. Zato so bili kakor onesnaženi, odstranjeni od duhovništva.',
        65: '§ Tirsata jim je rekel, da naj ne jedo od najsvetejših stvari, dokler tam ne vstane duhovnik z urimom in tumimom.',
        66: 'Celotne skupnosti skupaj je bilo dvainštirideset tisoč tristo šestdeset,',
        67: 'poleg njihovih slug in njihovih dekel, od katerih jih je bilo tam sedem tisoč tristo sedemintrideset. Imeli so dvesto petinštirideset pevcev in pevk.',
        68: 'Njihovih konj sedemsto šestintrideset, njihovih mul dvesto petinštirideset,',
        69: 'njihovih kamel štiristo petintrideset in šest tisoč sedemsto dvajset oslov.',
        70: 'Nekateri izmed vodij očetov so darovali k delu. Tirsata je dal v zaklad tisoč darejkov zlata, petdeset umivalnikov in petsto trideset duhovniških oblačil.',
        71: 'Nekateri izmed vodij očetov so dali v zaklad za delo dvajset tisoč darejkov zlata in dva tisoč dvesto funtov srebra.',
        72: 'Tega, kar je dalo ostalo ljudstvo, je bilo dvajset tisoč darejkov zlata, dva tisoč funtov srebra in sedeminšestdeset duhovniških oblačil.',
        73: 'Tako so duhovniki, Lévijevci, vratarji, pevci, nekateri izmed ljudstva, Netinimci in ves Izrael prebivali v svojih mestih. Ko je prišel sedmi mesec, so bili Izraelovi otroci v svojih mestih.‹',
    },
    8: {
        1: 'Vse ljudstvo se je zbralo skupaj kakor en mož na ulici, ki je bila pred vodnimi velikimi vrati in spregovorili so pisarju Ezru, da prinese knjigo Mojzesove postave, ki jo je Gospod zapovedal Izraelu.',
        2: 'Duhovnik Ezra je na prvi dan sedmega meseca postavo prinesel pred skupnost tako mož kakor žena in vseh tistih, ki so lahko slišali z razumevanjem.',
        3: 'Bral je tam pred ulico, ki je bila pred vodnimi velikimi vrati od jutra do sredine dneva, pred možmi in ženami in tistimi, ki so lahko razumeli. Ušesa vsega ljudstva so bila pozorna na knjigo postave.',
        4: 'Pisar Ezra je stal na leseni prižnici, ki so jo naredili za ta namen. Poleg njega so na njegovi desni roki stali: Matitjá, Šemaá, Anajá, Urijá, Hilkijá in Maasejá, na njegovi levi roki pa: Pedajá, Mišaél, Malkijá, Hašúm, Hašbadána, Zeharjá in Mešulám.',
        5: '§ Ezra je odprl knjigo v pogledu vsega ljudstva (kajti on je bil nad vsem ljudstvom); in ko jo je odprl, je vse ljudstvo vstalo.',
        6: 'Ezra je blagoslovil Gospoda, vélikega Boga. In vse ljudstvo je z dviganjem svojih rok odgovarjalo: »Amen, amen.« In sklonili so svoje glave ter oboževali Gospoda s svojimi obrazi k tlom.',
        7: 'Tudi Ješúa, Baní, Šerebjá, Jamín, Akúb, Šabetáj, Hodijá, Maasejá, Kelitá, Azarjá, Jozabád, Hanán, Pelajá in Lévijevci so storili ljudstvu, da je razumelo postavo in ljudstvo je stalo na svojem mestu.',
        8: 'Tako so razločno brali v knjigi Božje postave in dali pomen in jim storili, da razumejo branje.',
        9: 'Nehemija, ki je Tirsata in pisar Ezra, duhovnik in Lévijevci, ki so učili ljudstvo, so vsemu ljudstvu rekli: »Ta dan je svet Gospodu, svojemu Bogu; ne žalujte niti ne jokajte.« Kajti vse ljudstvo je jokalo, ko so slišali besede postave.',
        10: 'Potem jim je rekel: »Pojdite svojo pot, jejte tolščo, pijte sladko in pošljite deleže tistim, za katere ni ničesar pripravljenega, kajti ta dan je svet našemu Gospodu. Niti ne bodite žalostni, kajti Gospodova radost je vaša moč.«',
        11: 'Tako so Lévijevci umirili vse ljudstvo, rekoč: »Ohranite svoj mir, kajti dan je svet. Niti ne bodite užaloščeni.«',
        12: 'In vse ljudstvo je odšlo svojo pot, da jedo in da pijejo in da pošljejo deleže in da naredijo veliko veselje, ker so razumeli besede, ki so jim bile naznanjene.',
        13: 'Na drugi dan so bili zbrani skupaj vodje očetov izmed vsega ljudstva, duhovniki in Lévijevci, k pisarju Ezru, celo da razumejo besede iz postave.',
        14: 'In našli so zapisano v postavi, ki jo je Gospod zapovedal po Mojzesu, da naj bi Izraelovi otroci na praznik sedmega meseca prebivali v šotorih',
        15: 'in da naj bi objavili in razglasili po vseh svojih mestih in v Jeruzalemu, rekoč: »Pojdite naprej na goro in naberite oljčne mladike, borove mladike, mirtine mladike, mladike palm in mladike debelih dreves, da naredite šotore, kakor je to pisano.«',
        16: 'Tako je ljudstvo šlo naprej in jih prineslo in si naredilo šotore, vsak na strehi svoje hiše, na svojih dvorih, na dvorih Božje hiše, na ulici Vodnih velikih vrat in na ulici Efrájimovih velikih vrat.',
        17: 'Vsa skupnost izmed teh, ki so ponovno prišli iz ujetništva, si je naredila šotore in sedela pod šotori, kajti od dni Nunovega sina Ješúa do tega dne Izraelovi otroci niso tako storili. In tam je bilo zelo veliko veselje.',
        18: 'Tudi dan za dnem, od prvega dne do zadnjega dne, je bral v knjigi Božje postave. Praznovanje so imeli sedem dni, na osmi dan pa je bil slovesen zbor, glede na običaj.',
    },
    9: {
        1: 'Torej na štiriindvajseti dan tega meseca so se Izraelovi otroci zbrali s postom in z vrečevinami in prstjo na sebi.',
        2: 'Izraelovo seme se je ločilo od vseh tujcev in stali so ter priznavali svoje grehe in krivičnosti svojih očetov.',
        3: 'Vstali so na svojem kraju in brali v knjigi postave Gospoda, svojega Boga, eno četrtino dneva. Drugo četrtino pa so priznavali in oboževali Gospoda, svojega Boga.',
        4: 'Tedaj so vstali na stopnicah izmed Lévijevcev: Ješúa, Baní, Kadmiél, Šebanjá, Buní, Šerebjá, Baní in Kenáni in z močnim glasom vpili h Gospodu, svojemu Bogu.',
        5: 'Potem so Lévijevci Ješúa, Kadmiél, Baní, Hašabnejá, Šerebjá, Hodijá, Šebanjá in Petahjá rekli: »Vstanite in blagoslavljajte Gospoda, svojega Boga, na veke vekov in blagoslovljeno bodi tvoje veličastno ime, ki je vzvišeno nad vsem blagoslavljanjem in hvalo.«',
        6: 'Ti, celó ti sam si Gospod. Naredil si nebo in nebesa nebes, z vso njihovo vojsko, zemljo in vse stvari, ki so na njej, morja in vse, kar je v njih in ti jih vse ohranjaš in nebeška vojska te obožuje.',
        7: 'Ti si Gospod Bog, ki je izbral Abrama in ga privedel naprej iz Ura Kaldejcev in si mu dal ime Abraham.',
        8: 'Njegovo srce si pred seboj našel zvesto in z njim si sklenil zavezo, da daš deželo Kánaancev, Hetejcev, Amoréjcev, Perizéjcev, Jebusejcev in Girgašéjcev, da jo daš, pravim, njegovemu semenu in izvršil si svoje besede, kajti pravičen si.',
        9: 'Videl si stisko naših očetov v Egiptu in prisluhnil njihovemu vpitju pri Rdečem morju',
        10: 'in pokazal si znamenja in čudeže na faraonu in na vseh njegovih služabnikih in na vsemu ljudstvu njegove dežele, kajti ti veš, da so ponosno postopali zoper njih. Tako si si pridobil ime, kakor je to ta dan.',
        11: 'Pred njimi si razdelil morje, tako da so šli skozi sredo morja po suhi deželi. Njihove preganjalce si vrgel v globine kakor kamen v sredo mogočnih vodá.',
        12: 'Poleg tega si jih podnevi vodil z oblačnim stebrom in ponoči z ognjenim stebrom, da bi jim dal svetlobo na poti, po kateri naj bi šli.',
        13: 'Ti si tudi prihajal dol na goro Sinaj in govoril z njimi iz nebes in jim dajal prave sodbe in resnične postave, dobre zakone in zapovedi.',
        14: 'Dal si jim spoznati svoj sveti šabat in jim zapovedal predpise, zakone in postave, po roki svojega služabnika Mojzesa',
        15: 'in dajal si jim kruh iz nebes za njihovo lakoto in zanje si za njihovo žejo privedel vodo iz skale in jim obljubljal, da naj bi šli in vzeli v last deželo, ki si jim jo prisegel, da jim jo daš.',
        16: 'Toda oni in naši očetje so ponosno postopali in otrdili svoje vratove in niso prisluhnili tvojim zapovedim',
        17: 'in odklonili so ubogati niti niso razmišljali o tvojih čudežih, ki si jih storil med njimi, temveč so otrdili svoje vratove in v svojem uporu so določili poveljnika, da se vrnejo k svojemu suženjstvu. Toda ti si Bog, pripravljen odpustiti, milostljiv in usmiljen, počasen za jezo in velike prijaznosti in jih nisi zapustil.',
        18: 'Da, ko so si naredili ulito tele in rekli: »To je tvoj Bog, ki te je privedel iz Egipta,« in počeli so veliko izzivanj,',
        19: 'jih vendar ti v svojih mnogoterih usmiljenih nisi zapustil v divjini. Podnevi oblačen steber ni odšel od njih, da jih vodi po poti niti ognjeni steber ponoči, da jim kaže svetlobo in pot, po kateri naj bi šli.',
        20: 'Dajal si jim tudi svojega dobrega duha, da jih pouči in pred njihovimi usti nisi zadržal mane in za njihovo žejo si jim dajal vodo.',
        21: 'Da, štirideset let si jih podpiral v divjini, tako da jim ničesar ni manjkalo. Njihova oblačila se niso postarala in njihova stopala niso otekla.',
        22: 'Poleg tega si jim dajal kraljestva in narode in razdelil si jih po pokrajinah. Tako so vzeli v last deželo Sihón, deželo hešbónskega kralja in deželo bašánskega kralja Oga.',
        23: 'Tudi njihove otroke si pomnožil kakor zvezd na nebu in jih privedel v deželo, glede katere si njihovim očetom obljubil, da naj bi šli vanjo, da jo vzamejo v last.',
        24: 'Tako so otroci šli v deželo, jo vzeli v last in ti si pred njimi podjarmil prebivalce dežele, Kánaance in jih dal v njihove roke, z njihovimi kralji in ljudstvom dežele, da so lahko z njimi storili, kakor so hoteli.',
        25: 'Zavzeli so utrjena mesta in tolsto deželo in vzeli v last hiše, polne vseh dobrin, izkopane vodnjake, vinograde, oljčne nasade in sadnih dreves v obilju. Tako so jedli, bili nasičeni, se odebelili in se razveseljevali v tvoji veliki dobroti.',
        26: 'Kljub temu so bili neposlušni in so se uprli zoper tebe in tvojo postavo vrgli za svoje hrbte in usmrtili tvoje preroke, ki so pričevali zoper njih, da jih obrnejo k tebi in naredili so velika izzivanja.',
        27: 'Zato si jih izročil v roko njihovih sovražnikov, ki so jih stiskali. V času svoje stiske, ko so klicali k tebi, si jih uslišal iz nebes in glede na svoja mnogotera usmiljenja si jim dal rešitelje, ki so jih rešili iz roke njihovih sovražnikov.',
        28: 'Toda potem, ko so imeli počitek, so pred teboj ponovno storili zlo. Zato si jih pustil v roki njihovih sovražnikov, tako da so imeli gospostvo nad njimi. Vendar ko so se vrnili in klicali k tebi, si jih slišal iz nebes in mnogokrat si jih osvobodil glede na svoja usmiljenja.',
        29: 'In ti pričuješ zoper njih, da bi jih lahko ponovno privedel k svoji postavi. Vendar so ponosno postopali in niso prisluhnili tvojim zapovedim, temveč so grešili zoper tvoje sodbe (katere, če jih človek izpolnjuje, bo živel v njih) in umaknili ramo in otrdili svoj vrat in niso hoteli prisluhniti.',
        30: 'Vendar si jih mnogo let prenašal in zoper njih pričeval po svojem duhu v svojih prerokih, vendar niso hoteli pazljivo prisluhniti. Zato si jih dajal v roko ljudstvu dežel.',
        31: 'Vendar jih zaradi svojih velikih usmiljenj nisi popolnoma použil niti zapustil, kajti ti si usmiljen in milostljiv Bog.',
        32: 'Zdaj torej, naš Bog, velik, mogočen in strašen Bog, ki ohranjaš zavezo in usmiljenje, naj se vsa stiska, ki je prišla nad nas, na naše kralje, na naše prince, na naše duhovnike, na naše očete in na vse tvoje ljudstvo, od časa asirskih kraljev do današnjega dne, ne zdi majhna pred teboj.',
        33: 'Vendar si ti pravičen v vsem, kar si privedel nad nas, kajti storil si pravilno, toda mi smo storili zlobno.',
        34: 'Niti se naši kralji, naši princi, naši duhovniki, niti naši očetje, niso držali tvoje postave, niti niso prisluhnili tvojim zapovedim in tvojim pričevanjem, s katerimi si pričeval zoper njih.',
        35: 'Kajti niso služili tebi v svojem kraljestvu in v tvoji veliki dobroti, ki jim jo daješ v veliki in obilni deželi, ki jo postavljaš prednje niti se niso odvrnili od svojih zlobnih del.',
        36: 'Glej, mi smo ta dan služabniki in glede dežele, ki si jo dal našim očetom, da jemo njen sad in njeno dobro, glej, mi smo služabniki v njej',
        37: 'in ta rojeva mnogo donosa kraljem, ki si jih zaradi naših grehov postavil nad nas. Prav tako imajo po njihovem užitku gospostvo nad našimi telesi in nad našo živino in mi smo v veliki stiski.',
        38: 'Zaradi vsega tega delamo zanesljivo zavezo in jo zapisujemo in naši princi, Lévijevci in duhovniki, jo pečatijo.',
    },
    10: {
        1: '§ Torej tisti, ki so pečatili, so bili: Nehemija, Hahaljájev sin Tirsata, Sedekíja,',
        2: '§ Serajá, Azarjá, Jeremija,',
        3: 'Pašhúr, Amarjá, Malkijá,',
        4: 'Hatúš, Šebanjá, Malúh,',
        5: 'Harím, Meremót, Obadjá,',
        6: 'Daniel, Ginetón, Baruh,',
        7: 'Mešulám, Abíja, Mijamín,',
        8: 'Maazjá, Bilgáj, Šemajá. Ti so bili duhovniki.',
        9: 'Lévijevci: tako Azanjájev sin Ješúa, Binúj izmed Henadádovih sinov, Kadmiél,',
        10: 'kakor njihovi bratje: Šebanjá, Hodijá, Kelitá, Pelajá, Hanán,',
        11: 'Miha, Rehób, Hašabjá,',
        12: 'Zahúr, Šerebjá, Šebanjá,',
        13: 'Hodijá, Baní, Benínu.',
        14: 'Vodje ljudstva: Paróš, Pahat Moáb, Elám, Zatú, Baní,',
        15: 'Buní, Azgád, Bebáj,',
        16: 'Adoníja, Bigváj, Adín,',
        17: 'Atêr, Ezekíja, Azúr,',
        18: 'Hodijá, Hašúm, Becáj,',
        19: 'Haríf, Anatót, Nebáj,',
        20: 'Magpiáš, Mešulám, Hezír,',
        21: 'Mešezabél, Cadók, Jadúa,',
        22: 'Pelatjá, Hanán, Anajá,',
        23: 'Hošéa, Hananjá, Hašúb,',
        24: 'Lohéš, Pilhá, Šobék,',
        25: 'Rehúm, Hašabná, Maasejá,',
        26: 'Ahíja, Hanán, Anán,',
        27: 'Malúh, Harím in Baaná.',
        28: 'Preostanek ljudstva, duhovniki, Lévijevci, vratarji, pevci, Netinimci in vsi, ki so se ločili od ljudstva dežel k postavi Boga, njihove žene, njihovi sinovi in njihove hčere, vsak, ki je imel spoznanje in imel razumevanje,',
        29: 'so se pridružili k svojim bratom, svojim plemičem in vstopili v prekletstvo in prisego, da se ravnajo po Božji postavi, ki je bila dana po Mojzesu, Božjemu služabniku in da obeležujejo in delajo vse zapovedi Gospoda, našega Gospoda, njegove sodbe in njegove zakone,',
        30: 'in da mi ne bi dajali svojih hčera ljudstvu dežele niti jemali njihovih hčera za naše sinove.',
        31: 'Če ljudstvo dežele prinese blago ali kakršen koli živež na šabatni dan, da prodaja, da mi tega ne bomo kupovali od njih na šabat ali na sveti dan in da bomo pustili sedmo leto in izterjavo vsakega dolga.',
        32: 'Prav tako smo naredili odredbe za sebe, da se letno obremenimo s tretjino šekla za službo hiše svojega Boga,',
        33: 'za hlebe navzočnosti in za nenehno jedilno daritev in za nenehno žgalno daritev od šabat, od mlajev, za določene praznike, za svete stvari in za daritve za greh, da se naredi odkupitev za Izrael in za vse delo hiše svojega Boga.',
        34: 'Vrgli smo žrebe med duhovniki, Lévijevci in ljudstvom za dar lesa, da bi ga prinašali v hišo svojega Boga, glede na hiše naših očetov, ob določenih časih, leto za letom, da [ga] zažigamo na oltarju Gospoda, svojega Boga, kakor je to zapisano v postavi',
        35: 'in da prinašamo prve sadove svojih tal in prve sadove vsega sadja od vseh dreves, leto za letom, v Gospodovo hišo.',
        36: 'Tudi prvorojenca naših sinov in naše živine, kakor je to zapisano v postavi in prvence naših čred in naših tropov, da jih privedemo k hiši svojega Boga, k duhovnikom, ki služijo v hiši našega Boga',
        37: 'In da naj bi prinesli prve sadove našega testa in naših daritev in sad vseh vrst dreves, od vina in od olja, k duhovnikom, k sobam hiše našega Boga in desetine naših tal k Lévijevcem, da bodo isti Lévijevci lahko imeli desetine v vseh mestih našega posevka.',
        38: 'Duhovnik, Aronov sin, bo z Lévijevci, ko bodo Lévijevci prejemali desetine in Lévijevci bodo prinesli gor desetino od desetin k hiši našega Boga, k sobam, v zakladno hišo.',
        39: 'Kajti Izraelovi otroci in Lévijevi otroci bodo prinašali daritev žita, od novega vina in olja, v sobe, kjer so posode svetišča in duhovniki, ki služijo in vratarji in pevci. Ne bomo zapustili hiše svojega Boga.',
    },
    11: {
        1: 'Voditelji ljudstva so prebivali pri Jeruzalemu. Ostali ljudje pa so prav tako metali žrebe, da privedejo enega izmed desetih, da prebiva v Jeruzalemu, svetemu mestu in devet delov, da prebivajo v drugih mestih.',
        2: 'Ljudstvo je blagoslovilo vse može, ki so se voljno ponudili, da prebivajo v Jeruzalemu.',
        3: 'Torej ti so vodje province, ki so prebivali v Jeruzalemu. Toda v judejskih mestih je vsak prebival na svoji posesti v svojih mestih, namreč Izrael, duhovniki, Lévijevci, Netinimci in otroci Salomonovih služabnikov.',
        4: 'V Jeruzalemu so prebivali nekateri izmed Judovih otrok in izmed Benjaminovih otrok. Izmed Judovih otrok: Atajá, sin Uzíjaha, sinú Zeharjá, sinú Amarjá, sinú Šefatjá, sinú Mahalaléla, izmed Perecovih otrok',
        5: 'in Maasejája, sin Baruha, sinú Kolhozéja, sinú Hazajája, sinú Adajája, sinú Jojaríba, sinú Zeharjá, sinú Šilčana.',
        6: 'Vseh Perecovih sinov, ki so prebivali v Jeruzalemu, je bilo štiristo oseminšestdeset hrabrih mož.',
        7: 'To so Benjaminovi sinovi: Salú, sin Mešuláma, sinú Joéda, sinú Pedajá, sinú Kolajája, sinú Maasejája, sinú Itiéla, sinú Ješajája.',
        8: 'In za njim Gabáj, Saláj, devetsto osemindvajset.',
        9: 'Zihríjev sin Joél je bil njihov nadzornik, Senuájev sin Juda pa je bil drugi nad mestom.',
        10: 'Od duhovnikov: Jojaríbov sin Jedajá, Jahín.',
        11: 'Serajá, sin Hilkijája, sinú Mešuláma, sinú Cadóka, sinú Merajóta, sinú Ahitúba, je bil poveljnik Božje hiše.',
        12: 'Njihovih bratov, ki so opravljali delo hiše, je bilo osemsto dvaindvajset. Adajá, sin Jeroháma, sinú Pelaljája, sinú Amcíja, sinú Zeharjá, sinú Pašhúrja, Malkijájevega sina',
        13: 'in njegovi bratje, vodje očetov, dvesto dvainštirideset. Amašsáj, sin Azaréla, sinú Ahzája, sinú Mešilemóta, sinú Imêrja',
        14: 'in njihovi bratje, močni junaški možje, sto osemindvajset. Njihov nadzornik je bil Zabdiél, sin enega izmed velikih mož.',
        15: 'Tudi izmed Lévijevcev: Šemajá, sin Hašúba, sinú Azrikáma, sinú Hašabjája, sinú Buníja.',
        16: 'Šabetáj ter Jozabád izmed vodij Lévijevcev sta imela nadzor nad zunanjim poslom Božje hiše.',
        17: 'Matanjá, sin Miha, sinú Zabdíja, sinú Asáfa, je bil glavni, da prične zahvaljevanje v molitvi. Bakbukjá, drugi med njegovimi brati in Abdá, sin Šamúaja, sinú Galála, sinú Jedutúna.',
        18: 'Vseh Lévijevcev v svetem mestu je bilo dvesto štiriinosemdeset.',
        19: 'Poleg tega vratarji: Akúb, Talmón in njuni bratje, ki so varovali velika vrata, jih je bilo sto dvainsedemdeset.',
        20: 'Preostanek Izraela, od duhovnikov in Lévijevcev, je bil v vseh Judovih mestih, vsak v svoji dediščini.',
        21: 'Toda Netinimci so prebivali v Ofelu. Cihá in Gišpá pa sta bila nad Netinimci.',
        22: 'Nadzornik Lévijevcev v Jeruzalemu je bil tudi Uzí, sin Baníja, sinú Hašabjája, sinú Matanjája, sinú Miha. Izmed Asáfovih sinov so bili pevci nad poslom Božje hiše.',
        23: 'Kajti to je bila kraljeva zapoved glede njih, da naj bo določen delež za pevce, kar jim je pripadalo za vsak dan.',
        24: 'Petahjá, sin Mešezabéla, izmed otrok Judovega sina Zeraha je bil pri kraljevi roki v vseh zadevah glede ljudstva.',
        25: 'Glede vasi, z njihovimi polji, so nekateri izmed Judovih otrok prebivali pri Kirját Arbi in v njenih vaseh, pri Dibónu in v njegovih vaseh, pri Kabceélu in v njegovih vaseh,',
        26: 'pri Ješúi, pri Moládi, pri Bet Peletu,',
        27: 'pri Hacár Šuál in pri Beeršébi in v njenih vaseh,',
        28: 'pri Ciklágu, pri Mehóni in v njegovih vaseh,',
        29: 'pri En Rimónu, pri Cori, pri Jarmútu,',
        30: 'Zanóahu, Adulámu in v njihovih vaseh, pri Lahíšu in njegovih poljih, pri Azéki in v njenih vaseh. In prebivali so od Beeršébe, do doline Hinóm.',
        31: 'Tudi otroci Benjamina iz Gebe so prebivali pri Mihmášu, Aji, Betelu in v njihovih vaseh',
        32: 'in pri Anatótu, Nobu, Ananjáju,',
        33: 'Hacórju, Rami, Gitájimu,',
        34: 'Hadídu, Cebojímu, Nebalátu,',
        35: 'Lodu in Onóju, dolini rokodelcev.',
        36: 'Izmed Lévijevcev so bili oddelki v Judu in v Benjaminu.',
    },
    12: {
        1: 'Torej to so duhovniki in Lévijevci, ki so prišli gor z Zerubabélom, Šealtiélovim sinom in Ješúom: Serajá, Jeremija, Ezra,',
        2: 'Amarjá, Malúh, Hatúš,',
        3: 'Šehanjá, Rehúm, Meremót,',
        4: 'Idó, Ginetó, Abíja,',
        5: 'Mijamín, Maadjá, Bilgá,',
        6: 'Šemajá, Jojaríb, Jedajája,',
        7: 'Salú, Amók, Hilkijá, Jedajája. Ti so bili vodje duhovnikov in njihovih bratov v dneh Ješúa.',
        8: 'Poleg tega Lévijevci: Ješúa, Binúj, Kadmiél, Šerebjá, Juda in Matanjá, ki je bil nad zahvaljevanjem, on in njegovi bratje.',
        9: 'Tudi Bakbukjá in Uní, njihova brata, sta bila njim nasproti na stražah.',
        10: 'Ješúa je zaplodil Jojakíma, Jojakím je zaplodil tudi Eljašíba, Eljašíb je zaplodil Jojadá,',
        11: 'Jojadá je zaplodil Jonatana in Jonatan je zaplodil Jadúa.',
        12: 'V dneh Jojakíma so bili duhovniki, vodja očetov: od Serajáma Merajá, od Jeremija Hananjá,',
        13: 'od Ezra Mešulám, od Amarjá Johanán,',
        14: 'od Melicuja Jonatan, od Šebanjá Jožef,',
        15: 'od Haríma Adná, od Merajóta Helkáj,',
        16: 'od Idója Zaharija, od Ginetóna Mešulám,',
        17: 'od Abíja Zihrí, od Minjamína, od Moadjája Piltáj,',
        18: 'od Bilgája Šamúa, od Šemajája Jehonatan,',
        19: 'in od Jojaríba Matenáj, od Jedajája Uzí,',
        20: 'od Salája Kaláj, od Amóka Eber,',
        21: 'od Hilkijá Hašabjá, od Jedajája, Netanél.',
        22: 'Lévijevci v dneh Eljašíba, Jojadája, Johanána in Jadúa so bili zabeleženi vodje očetov, tudi duhovniki, do kraljevanja Perzijca Dareja.',
        23: 'Lévijevi sinovi, vodje očetov so bili zapisani v kroniški knjigi, celo do dni Eljašíbovega sina Johanána.',
        24: 'Vodje Lévijevcev: Hašabjá, Šerebjá in Kadmiélov sin Ješúa z njihovimi brati nasproti njih, da hvalijo in da se zahvaljujejo, glede na zapoved Davida, Božjega moža, straža nasproti straži.',
        25: 'Matanjá in Bakbukjá, Obadjá, Mešulám, Talmón, Akúb so bili vratarji, ki so varovali stražo pri pragovih velikih vrat.',
        26: 'Ti so bili v dneh Jojakíma, sina Ješúa, sinú Jocadákovega in v dneh voditelja Nehemija in preroka Ezra, pisarja.',
        27: 'Ob posvetitvi jeruzalemskega obzidja so iskali Lévijevce iz vseh njihovih krajev, da jih privedejo v Jeruzalem, da ohranjajo posvetitev z veseljem, tako z zahvaljevanjem kakor s petjem, s cimbalami, plunkami in harfami.',
        28: 'Sinovi pevcev so se zbrali skupaj, tako iz ravne dežele okoli Jeruzalema kakor iz vasi Netófčanov,',
        29: 'tudi iz hiše Gilgála in iz gebskih in azmávetskih polj, kajti pevcem so zgradili vasi okoli Jeruzalema.',
        30: 'Duhovniki in Lévijevci so očistili sebe, očistili ljudstvo in velika vrata ter obzidje.',
        31: 'Potem sem na obzidje privedel Judove prince in določil dve veliki skupini tistih, ki so dajali zahvalo, od katerih je ena odšla na desno roko, po obzidju, h Gnojnim velikim vratom.',
        32: 'Za njimi je odšel Hošajá in polovica Judovih princev',
        33: 'Azarjá, Ezra, Mešulám,',
        34: 'Juda, Benjamin, Šemajá in Jeremija.',
        35: 'Nekateri izmed duhovnikovih sinov s trobentami, namreč Zeharjá, sin Jonatana, sinú Šemajá, sinú Matanjá, sinú Mihajája, sinú Zahúrja, sinú Asáfa',
        36: 'in njegovi bratje: Šemajá, Azarél, Milaláj, Gilaláj, Maáj, Netanél, Juda in Hananí z glasbenimi instrumenti Davida, Božjega moža in pisar Ezra pred njimi.',
        37: 'Pri Studenčnih velikih vratih, ki so bila nasproti njim, so se po stopnicah Davidovega mesta povzpeli ob vzponu obzidja, nad Davidovo hišo, celo do Vodnih velikih vrat proti vzhodu.',
        38: 'Druga skupina izmed tistih, ki so dajali zahvalo, pa je šla nasproti njim in jaz za njimi in polovica ljudstva na zidu od onstran stolpa talilnih peči, celo do širokega zidu',
        39: 'in nad Efrájimovimi velikimi vrati, nad Starimi velikimi vrati, nad Ribjimi velikimi vrati in [mimo] stolpa Hananéla in stolpa Mea, torej do Ovčjih velikih vrat in so mirno obstali pri Jetniških velikih vratih.',
        40: 'Tako sta stali dve skupini izmed tistih, ki so dajali zahvalo v Božji hiši ter jaz in polovica vladarjev z menoj',
        41: 'in duhovniki: Eljakím, Maasejája, Minjamín, Mihajá, Eljoenáj, Zeharjá in Hananjá s trobentami',
        42: 'ter Maasejája, Šemajá, Eleazar, Uzí, Johanán, Malkijája, Elám in Ecer. Pevci so glasno peli z Jizrahjájem, njihovim nadzornikom.',
        43: 'Ta dan so darovali tudi veliko klavnih daritev in se veselili, kajti Bog jih je pripravil, da se veselijo z veliko radostjo. Tudi žene in otroci so se veselili, tako da je bilo veselje iz Jeruzalema slišati celo od daleč.',
        44: 'Ob tistem času so bili nekateri določeni nad sobe za zaklade, za daritve, za prve sadove in za desetine, da zberejo vanje iz mestnih polj deleže od postave za duhovnike in Lévijevce, kajti Juda se je veselil zaradi duhovnikov in Lévijevcev, ki so čakali.',
        45: 'Tako pevci kakor vratarji so varovali službo svojega Boga in službo očiščevanja, glede na zapoved Davida in njegovega sina Salomona.',
        46: 'Kajti v dneh Davida in Asáfa, so bili tam od davnine vodje pevcev s pesmimi hvaljenja in zahvaljevanja Bogu.',
        47: 'Ves Izrael je v dneh Zerubabéla in v dneh Nehemija dal deleže pevcem in vratarjem, vsak dan njegov delež. Svete stvari pa so posvetili Lévijevcem in Lévijevci so jih posvetili Aronovim otrokom.',
    },
    13: {
        1: 'Na ta dan so brali Mojzesovo knjigo v občinstvu ljudstva in v njej je bilo najdeno zapisano, da naj Amónec in Moábec na veke ne bi prišla v Božjo skupnost,',
        2: 'ker niso srečali Izraelovih otrok s kruhom in vodo, temveč so zoper njih najeli Bileáma, da bi jih preklel. Vendar je naš Bog prekletstvo obrnil na blagoslov.',
        3: 'Pripetilo se je torej, ko so slišali postavo, da so se od Izraela ločile vse mešane množice.',
        4: 'Pred tem je bil duhovnik Eljašíb, ki je imel nadzor nad sobo hiše našega Boga, zbližan k Tobiju',
        5: 'in zanj pripravil veliko sobo, kjer so vnaprej položili jedilne daritve, kadilo, posode, desetine od žita, novega vina in olja, kar je bilo zapovedano, da naj bo dano Lévijevcem, pevcem in vratarjem ter darove duhovnikom.',
        6: 'Toda v vsem tem času nisem bil v Jeruzalemu, kajti v dvaintridesetem letu babilonskega kralja Artakserksa sem prišel h kralju in po določenih dneh sem od kralja prejel dovoljenje za odhod',
        7: 'in prišel sem v Jeruzalem in razumel zlo, ki ga je Eljašíb storil Tobiju, s tem, da mu je pripravil sobo na dvorih Božje hiše.',
        8: 'To me je boleče užalostilo, zato sem iz sobe vrgel ven vse Tobijeve gospodinjske stvari.',
        9: 'Potem sem zapovedal in očistili so sobe. Tja sem ponovno prinesel posode iz Božje hiše, z jedilno daritvijo in kadilom.',
        10: 'Zaznal sem, da jim niso bili dani deleži Lévijevcev, kajti Lévijevci in pevci, ki so opravljali delo, so pobegnili vsak k svojemu polju.',
        11: 'Potem sem se pričkal s poveljniki in rekel: »Zakaj je Božja hiša zapuščena?« Zbral sem jih skupaj in jih postavil na njihov kraj.',
        12: 'Potem je ves Juda prinesel desetino od žita, novega vina in olja v zakladnice.',
        13: 'Postavil sem zakladnike nad zakladnicami: duhovnika Šelemjája, pisarja Cadóka in izmed Lévijevcev Pedajá. Poleg njih je bil Hanán, sin Zahúrja, sinú Matanjá, kajti bili so šteti zveste in njihova služba je bila, da razdeljujejo svojim bratom.',
        14: '»Spomni se me, oh moj Bog, glede tega in ne izbriši mojih dobrih dejanj, ki sem jih storil za hišo svojega Boga in za njene službe.«',
        15: 'V tistih dneh sem na šabat videl v Judu nekatere tlačiti vinske stiskalnice, prinašati snope in natovarjati osle kakor tudi vino, grozdje, fige in vse vrste bremen, ki so jih na šabatni dan prinesli v Jeruzalem. Pričeval sem zoper njih na dan, na katerega so prodajali živež.',
        16: 'Tam notri so prebivali tudi možje iz Tira, ki so prinašali ribe in vse vrste blaga in na šabatni dan prodajali Judovim otrokom in v Jeruzalemu.',
        17: 'Potem sem se pričkal z Judovimi plemiči in jim rekel: »Kakšno zlo je to, ki ga delate in oskrunjate šabatni dan?',
        18: 'Mar niso tako počeli vaši očetje in ali ni naš Bog privedel vsega tega zla nad nas in nad to mesto? Vendar nad Izrael prinašate več besa z oskrunitvijo šabata.«',
        19: 'Pripetilo se je, ko so jeruzalemska velika vrata pred šabat pričenjala temneti, da sem zapovedal, naj se velika vrata zapro in jih zadolžil, da naj ne bodo odprta, dokler ne mine šabat in nekatere izmed svojih služabnikov sem postavil pri velikih vratih, da na šabatni dan ne bi bilo noter privedeno nobeno breme.',
        20: 'Tako so trgovci in prodajalci vseh vrst blaga enkrat ali dvakrat prenočili zunaj Jeruzalema.',
        21: 'Potem sem pričeval zoper njih in jim rekel: »Zakaj prenočujete okoli obzidja? Če boste ponovno storili tako, bom svoje roke položil na vas.« Od tistega časa naprej niso več prihajali na šabat.',
        22: 'Lévijevcem sem zapovedal, da naj se očistijo in da naj pridejo in varujejo velika vrata, da posvetijo šabatni dan. »Spomni se me, oh moj Bog, tudi glede tega in prizanesi mi glede na veličino svojega usmiljenja.«',
        23: 'V tistih dneh sem videl tudi Jude, ki so poročili žene iz Ašdóda, iz Amóna in iz Moába',
        24: 'in njihovi otroci so govorili pol v ašdódskem jeziku in niso mogli govoriti judovskega jezika, temveč glede na jezik vsakega ljudstva.',
        25: 'Pričkal sem se z njimi in jih preklel in udaril nekatere izmed njih, izpulil njihove lase in jih primoral, da so prisegli pri Bogu, rekoč: »Svojih hčera ne boste dajali njihovim sinovom niti ne boste jemali njihovih hčera za svoje sinove ali zase.«',
        26: 'Mar ni Salomon, Izraelov kralj, grešil s temi stvarmi? Pa vendar med mnogimi narodi ni bilo nobenega kralja, podobnega njemu, ki je bil ljubljen od svojega Boga in ga je Bog postavil [za] kralja nad vsem Izraelom. Kljub temu so celo njemu tuje žene povzročile, da je grešil.',
        27: 'Mar naj potem prisluhnemo vam, da bi delali vso to veliko zlo, da grešimo zoper svojega Boga v poročanju tujih žena?',
        28: 'Eden izmed sinov Jojadája, sin vélikega duhovnika Eljašíba, je bil zet Horónca Sanbaláta, zato sem ga pregnal od sebe.',
        29: '»Spomni se jih, oh moj Bog, ker so omadeževali duhovništvo in zavezo duhovništva in Lévijevcev.«',
        30: 'Tako sem jih očistil vseh tujcev in določil straže duhovnikov in Lévijevcev, vsakega pri svojem poslu',
        31: 'in za dar lesa, ob določenih časih in za prve sadove. »Spominjaj se me, oh moj Bog, za vselej.«',
    },
}
